import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"零基础术语词典：看不懂就回来查","description":"","frontmatter":{},"headers":[],"relativePath":"00-start/glossary.md","filePath":"00-start/glossary.md","lastUpdated":1791601077000}'),o={name:"00-start/glossary.md"};function i(s,t,n,l,h,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="零基础术语词典-看不懂就回来查" tabindex="-1">零基础术语词典：看不懂就回来查 <a class="header-anchor" href="#零基础术语词典-看不懂就回来查" aria-label="Permalink to &quot;零基础术语词典：看不懂就回来查&quot;">​</a></h1><blockquote><p>这页不是要求你背诵的单词表。<strong>第一次看到一个术语，不懂就回来查；能用自己的话解释就够了。</strong> 按学习顺序排，不按英文字母排。</p></blockquote><h2 id="第一组-最先遇到的-12-个词" tabindex="-1">第一组：最先遇到的 12 个词 <a class="header-anchor" href="#第一组-最先遇到的-12-个词" aria-label="Permalink to &quot;第一组：最先遇到的 12 个词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话白话解释</th><th>你熟悉的类比</th></tr></thead><tbody><tr><td>区块链 Blockchain</td><td>多台计算机按照协议共同维护可验证的状态和交易记录</td><td>多方共同维护的账本，不是单台 MySQL</td></tr><tr><td>智能合约 Smart Contract</td><td>部署到区块链，由网络规则执行的程序</td><td>放在链上的业务模块</td></tr><tr><td>Ethereum / 以太坊</td><td>支持智能合约的一条区块链生态/网络</td><td>不是一个具体 APP</td></tr><tr><td>EVM</td><td>执行合约字节码的虚拟机</td><td>有点像 Python 运行时，但有 Gas 和确定性规则</td></tr><tr><td>Solidity</td><td>常用于编写 EVM 智能合约的语言</td><td>类似你用 Python 写后端</td></tr><tr><td>地址 Address</td><td>标识账户或合约的公开编号</td><td>账号，但不等于真实身份</td></tr><tr><td>私钥 Private Key</td><td>授权交易的关键秘密材料</td><td>比密码更危险：泄露就可能失去资产控制</td></tr><tr><td>助记词 Seed Phrase</td><td>一种用于恢复钱包密钥的词语序列</td><td>极其敏感的恢复材料</td></tr><tr><td>钱包 Wallet</td><td>管理密钥、显示状态、发起签名的工具</td><td>用户端签名器，不是余额文件夹</td></tr><tr><td>交易 Transaction / Tx</td><td>向区块链提交的状态变更请求</td><td>有签名、有执行结果的写入操作</td></tr><tr><td>RPC / Node</td><td>查询区块链并提交交易的接口/节点</td><td>类似应用访问远程 API</td></tr><tr><td>Gas</td><td>为 EVM 操作计量的执行资源</td><td>不是 ETH 本身，类似资源计量</td></tr></tbody></table><h2 id="第二组-写-solidity-时会遇到" tabindex="-1">第二组：写 Solidity 时会遇到 <a class="header-anchor" href="#第二组-写-solidity-时会遇到" aria-label="Permalink to &quot;第二组：写 Solidity 时会遇到&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>白话解释</th><th>例子</th></tr></thead><tbody><tr><td>contract</td><td>一份合约声明</td><td><code>contract Counter</code></td></tr><tr><td>state / 状态</td><td>合约保存的当前数据</td><td><code>number</code> 现在是 2</td></tr><tr><td>uint256</td><td>不能为负的 256 位整数</td><td>计数、金额的最小单位</td></tr><tr><td>address</td><td>链上地址类型</td><td>买家地址、卖家地址</td></tr><tr><td>msg.sender</td><td>当前调用的直接发起者</td><td>用来做基础权限判断</td></tr><tr><td>msg.value</td><td>当前调用随交易发送的 wei 数量</td><td>向 payable 函数付钱</td></tr><tr><td>wei</td><td>ETH 的最小常用计价单位</td><td>1 ETH = 10^18 wei</td></tr><tr><td>constructor</td><td>部署时执行的构造函数</td><td>设定第一个 owner</td></tr><tr><td>public / external</td><td>函数/变量访问规则</td><td>可以从外部调用</td></tr><tr><td>view / pure</td><td>对函数读取状态、修改状态的限制</td><td>读取计数器</td></tr><tr><td>revert</td><td>取消本次调用的链上状态修改并报错</td><td>无权操作时拒绝</td></tr><tr><td>event / emit</td><td>定义并发出链上事件日志</td><td>记下谁加了计数</td></tr><tr><td>mapping</td><td>按键取值的存储结构</td><td>地址 → 余额</td></tr><tr><td>storage / memory / calldata</td><td>持久状态、临时内存和调用参数区</td><td>后面会逐个实验</td></tr></tbody></table><h2 id="第三组-进入工程后再认识" tabindex="-1">第三组：进入工程后再认识 <a class="header-anchor" href="#第三组-进入工程后再认识" aria-label="Permalink to &quot;第三组：进入工程后再认识&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>白话解释</th></tr></thead><tbody><tr><td>Remix</td><td>浏览器里的 Solidity 编辑、编译、部署实验环境</td></tr><tr><td>Foundry</td><td>Solidity 开发与测试工具集</td></tr><tr><td>forge</td><td>Foundry 中负责编译、测试的工具</td></tr><tr><td>anvil</td><td>Foundry 的本地开发链</td></tr><tr><td>cast</td><td>Foundry 的链上查询/编码命令行工具</td></tr><tr><td>ABI</td><td>告诉外部程序如何调用合约的接口描述</td></tr><tr><td>Bytecode</td><td>编译后供 EVM 执行的字节码</td></tr><tr><td>Receipt / 交易回执</td><td>可用来检查交易执行状态、Gas、日志的结果</td></tr><tr><td>Fuzz Testing</td><td>自动用大量不同输入尝试同一性质</td></tr><tr><td>Invariant / 不变量</td><td>系统无论怎样操作都必须维持的约束</td></tr><tr><td>Reentrancy / 重入</td><td>外部调用期间，对方再次回调进入你的合约</td></tr><tr><td>CEI</td><td>先检查、再更新状态、最后交互的安全组织方式</td></tr><tr><td>ERC-20</td><td>以太坊可替代代币的常见接口标准</td></tr><tr><td>Escrow</td><td>托管资金，满足约定后释放或退款的业务模式</td></tr></tbody></table><h2 id="容易混淆的三组概念" tabindex="-1">容易混淆的三组概念 <a class="header-anchor" href="#容易混淆的三组概念" aria-label="Permalink to &quot;容易混淆的三组概念&quot;">​</a></h2><h3 id="地址、钱包、余额" tabindex="-1">地址、钱包、余额 <a class="header-anchor" href="#地址、钱包、余额" aria-label="Permalink to &quot;地址、钱包、余额&quot;">​</a></h3><p>地址是链上标识；钱包是帮助你管理密钥的软件/硬件；余额是链上的数据。<strong>卸载钱包软件不等于清空链上余额</strong>，但丢失恢复材料可能导致无法控制账户。</p><h3 id="gas、eth、手续费" tabindex="-1">Gas、ETH、手续费 <a class="header-anchor" href="#gas、eth、手续费" aria-label="Permalink to &quot;Gas、ETH、手续费&quot;">​</a></h3><p>Gas 是计算资源单位；ETH 是以太坊原生资产；网络交易费用在以太坊主网通常用 ETH 支付。<strong>Gas Used × Effective Gas Price</strong> 可用于理解执行费用，但 L2 可能还有其他收费项目。</p><h3 id="合约源码、abi、合约地址" tabindex="-1">合约源码、ABI、合约地址 <a class="header-anchor" href="#合约源码、abi、合约地址" aria-label="Permalink to &quot;合约源码、ABI、合约地址&quot;">​</a></h3><p>源码是你写的 Solidity；ABI 是调用接口描述；合约地址是一个已部署实例的地址。<strong>有源码不代表已部署，有地址不代表你拥有源代码</strong>。</p><h2 id="读不懂时怎么做" tabindex="-1">读不懂时怎么做 <a class="header-anchor" href="#读不懂时怎么做" aria-label="Permalink to &quot;读不懂时怎么做&quot;">​</a></h2><p>回到你正在读的章节，只问三件事：</p><ol><li><strong>这个东西是什么？</strong> 用上面的一句话翻译。</li><li><strong>谁在什么时候用它？</strong> 例如钱包在“签名交易”时使用私钥。</li><li><strong>我能在哪里看到它？</strong> 例如在 Remix 的账户列表看到地址，在终端看到 Gas Used。</li></ol><p>下一步：<a href="/00-start/">回到第 0 课</a> · <a href="/00-start/environment">直接动手做 Counter</a>。</p>',19)])])}const m=d(o,[["render",i]]);export{u as __pageData,m as default};
